_FONTS = {}


def _font(bold, size):
    key = (bold, size)
    if key in _FONTS:
        return _FONTS[key]
    b64 = FONT_BOLD_B64 if bold else FONT_REGULAR_B64
    fnt = None
    if b64:
        try:
            fnt = ImageFont.truetype(io.BytesIO(base64.b64decode(b64)), size)
        except Exception:
            fnt = None
    if fnt is None:
        fnt = ImageFont.load_default()
    _FONTS[key] = fnt
    return fnt


def _tw(d, text, fnt):
    return d.textlength(text, font=fnt)


def _wrap(d, text, fnt, max_w):
    words = text.split()
    lines = []
    cur = ""
    for w in words:
        t = (cur + " " + w).strip()
        if _tw(d, t, fnt) <= max_w or not cur:
            cur = t
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def _wrap_max(d, text, fnt, max_w, max_lines):
    lines = _wrap(d, text, fnt, max_w)
    if len(lines) <= max_lines:
        return lines
    lines = lines[:max_lines]
    last = lines[-1]
    while last and _tw(d, last + " ...", fnt) > max_w:
        last = last[:-1]
    lines[-1] = last.rstrip() + " ..."
    return lines


def _vgrad(d, x, y, w, h, c1, c2):
    for yy in range(h):
        t = yy / max(1, h - 1)
        c = tuple(int(c1[i] + (c2[i] - c1[i]) * t) for i in range(3))
        d.line([(x, y + yy), (x + w - 1, y + yy)], fill=c)


def _chip(d, x, y, text, color, fnt):
    w = int(_tw(d, text, fnt)) + 14
    d.rounded_rectangle([x, y, x + w, y + 16], radius=8, fill=color)
    d.text((x + 7, y + 3), text, font=fnt, fill=WHITE)
    return w


def _region_tab(d, x, y, region):
    fnt = _font(True, 9)
    w = int(_tw(d, region, fnt)) + 14
    color = REGION_COLORS[region]
    d.rounded_rectangle([x, y, x + w, y + 16], radius=3, fill=color)
    d.text((x + 7, y + 3), region, font=fnt, fill=WHITE)
    return w

