def _scene_ship(d, x, y, w, h):
    _vgrad(d, x, y, w, h, (168, 184, 202), (112, 130, 152))
    d.ellipse([x + 262, y + 6, x + 292, y + 36], fill=(235, 225, 190))
    _vgrad(d, x, y + 40, w, h - 40, (44, 76, 104), (22, 46, 70))
    d.line([(x, y + 40), (x + w, y + 40)], fill=(200, 215, 228), width=1)
    for wx in (x + 20, x + 90, x + 160, x + 230, x + 290):
        d.arc([wx, y + 46, wx + 22, y + 56], 180, 360, fill=(150, 175, 195))
    # cargo ship
    d.polygon([(x + 62, y + 44), (x + 258, y + 44), (x + 242, y + 62),
               (x + 78, y + 62)], fill=(28, 32, 38))
    for i, c in enumerate(((200, 60, 50), (40, 120, 180), (230, 170, 60))):
        d.rectangle([x + 80 + i * 34, y + 26, x + 110 + i * 34, y + 44], fill=c)
    d.rectangle([x + 196, y + 18, x + 226, y + 44], fill=(235, 235, 228))
    for wy in (22, 30, 38):
        d.rectangle([x + 200, y + wy, x + 222, y + wy + 3], fill=(40, 90, 130))
    d.rectangle([x + 232, y + 30, x + 238, y + 44], fill=(90, 90, 90))
    for i in range(3):
        d.ellipse([x + 228 + i * 6, y + 18 - i * 7, x + 240 + i * 6, y + 30 - i * 7],
                  fill=(200, 200, 200))
    # drone above
    d.polygon([(x + 120, y + 6), (x + 128, y + 2), (x + 136, y + 6),
               (x + 128, y + 10)], fill=(20, 20, 24))
    for dx in (112, 136):
        d.ellipse([x + dx, y + 2, x + dx + 8, y + 6], fill=(60, 60, 66))


