def _scene_gavel(d, x, y, w, h):
    _vgrad(d, x, y, w, h, (122, 86, 52), (78, 54, 30))
    for cx in (8, 296):
        d.rectangle([x + cx, y + 4, x + cx + 20, y + h], fill=(150, 112, 70))
        d.rectangle([x + cx - 3, y, x + cx + 23, y + 6], fill=(168, 130, 84))
    # sound block
    d.ellipse([x + 128, y + 48, x + 196, y + 62], fill=(96, 64, 34))
    # gavel head + handle, angled -28 degrees
    cx0, cy0 = x + 162, y + 30
    ang = math.radians(-28)
    ca, sa = math.cos(ang), math.sin(ang)

    def rot(px, py):
        return (cx0 + px * ca - py * sa, cy0 + px * sa + py * ca)

    head = [rot(px, py) for px, py in
            ((-30, -9), (30, -9), (30, 9), (-30, 9))]
    d.polygon(head, fill=(72, 48, 26))
    handle = [rot(px, py) for px, py in
              ((18, -3), (86, -3), (86, 3), (18, 3))]
    d.polygon(handle, fill=(52, 34, 18))
    d.ellipse([x + 96, y + 52, x + 100, y + 56], fill=(250, 220, 140))
    d.rectangle([x + 236, y + 40, x + 286, y + 58], fill=(235, 228, 210))
    d.line([(x + 242, y + 46), (x + 280, y + 46)], fill=(120, 110, 96), width=1)
    d.line([(x + 242, y + 52), (x + 272, y + 52)], fill=(120, 110, 96), width=1)


