    for sx, sy in ((18, 6), (300, 8)):
        d.ellipse([x + sx, y + sy, x + sx + 14, y + sy + 14], fill=(250, 250, 230))
        for a in range(8):
            ang = math.radians(a * 45)
            d.line([(x + sx + 7, y + sy + 7),
                    (x + sx + 7 + int(13 * math.cos(ang)),
                     y + sy + 7 + int(13 * math.sin(ang)))],
                   fill=(250, 250, 230), width=1)
    for cx in range(10, 316, 14):
        d.ellipse([x + cx, y + 26, x + cx + 5, y + 31], fill=(40, 60, 46))
