def _scene_debt(d, x, y, w, h):
    _vgrad(d, x, y, w, h, (28, 38, 68), (68, 88, 128))
    for bx, bw, bh in ((6, 34, 30), (46, 26, 44), (78, 40, 26), (250, 30, 38),
                       (286, 24, 28)):
        d.rectangle([x + bx, y + h - bh, x + bx + bw, y + h], fill=(14, 18, 34))
    for wx in (14, 54, 88, 258, 292):
        for wy in (y + h - 24, y + h - 14):
            d.rectangle([x + wx, wy, x + wx + 4, wy + 4], fill=(240, 210, 90))
    # banknotes
    fnt = _font(True, 14)
    for i, (nx, ny, ang) in enumerate(((96, 22, -8), (150, 14, 4), (204, 26, -3))):
        ca, sa = math.cos(math.radians(ang)), math.sin(math.radians(ang))
        cx0, cy0 = x + nx + 28, y + ny + 14
        pts = []
        for px, py in ((-28, -14), (28, -14), (28, 14), (-28, 14)):
            pts.append((cx0 + px * ca - py * sa, cy0 + px * sa + py * ca))
        d.polygon(pts, fill=(120, 170, 90))
        d.ellipse([cx0 - 9, cy0 - 9, cx0 + 9, cy0 + 9], outline=(40, 90, 40), width=2)
        d.text((cx0 - 5, cy0 - 8), "$", font=fnt, fill=(40, 90, 40))


def _scene_dow(d, x, y, w, h):
    _vgrad(d, x, y, w, h, (14, 30, 54), (28, 58, 98))
    for cx in (10, 44, 78):
        d.rectangle([x + cx, y + 34, x + cx + 24, y + h], fill=(150, 160, 180))
        d.rectangle([x + cx - 4, y + 30, x + cx + 28, y + 36], fill=(170, 180, 200))
    # rising chart
    pts = [(x + 120, y + 56), (x + 160, y + 48), (x + 195, y + 50),
           (x + 235, y + 34), (x + 270, y + 36), (x + 305, y + 14)]
    d.line(pts, fill=(90, 220, 140), width=4)
    d.polygon([(x + 305, y + 14), (x + 292, y + 12), (x + 300, y + 26)],
              fill=(90, 220, 140))
    for px, py in pts:
        d.ellipse([px - 3, py - 3, px + 3, py + 3], fill=(255, 255, 255))
    # bell
    bx, by = x + 252, y + 40
    d.polygon([(bx, by), (bx + 30, by), (bx + 26, by + 14), (bx + 4, by + 14)],
              fill=(232, 183, 76))
    d.ellipse([bx + 11, by + 14, bx + 19, by + 22], fill=(200, 150, 50))
    d.rectangle([bx - 4, by + 22, bx + 34, by + 26], fill=(200, 150, 50))

SCENES = {
    "ship": _scene_ship,
    "tower": _scene_tower,
    "memorial": _scene_memorial,
    "gavel": _scene_gavel,
    "chip": _scene_chip,
    "server": _scene_server,
    "batsman": _scene_batsman,
    "trophy": _scene_trophy,
    "stadium": _scene_stadium,
    "tape": _scene_tape,
    "debt": _scene_debt,
    "dow": _scene_dow,
}

# ---------------------------------------------------------------- layout
M = 14
GAP = 8
CW = 325
CH = 153
GRID_Y = 120


def _draw_header(d):
    d.rectangle([0, 0, W - 1, 111], fill=NAVY)
    d.rectangle([0, 112, W - 1, 114], fill=GOLD)
    d.text((24, 13), "MAKE.FUN  —  WORLD NEWS IN ONE IMAGE",
           font=_font(True, 11), fill=(150, 180, 220))
    d.text((24, 32), "THE WORLD IN ONE DAY", font=_font(True, 40), fill=WHITE)
    d.text((24, 80), "Wednesday 25 November 2026", font=_font(True, 17),
           fill=GOLD)
    f_big = _font(True, 22)
    t = "36 STORIES"
    d.text((1000 - _tw(d, t, f_big), 30), t, font=f_big, fill=WHITE)
    f_sm = _font(True, 11)
    t2 = "ACROSS 7 REGIONS"
    d.text((1000 - _tw(d, t2, f_sm), 60), t2, font=f_sm, fill=(150, 180, 220))
    t3 = "EVERY STORY VERIFIED  •  25 NOV 2026"
    d.text((1000 - _tw(d, t3, f_sm), 80), t3, font=f_sm, fill=(200, 205, 220))


def _draw_card(d, x, y, card):
    scene, region, source, stat, headline, detail = card
    d.rectangle([x, y, x + CW - 1, y + CH - 1], fill=CARD)
    SCENES[scene](d, x + 1, y + 1, CW - 2, 64)
    d.rectangle([x, y, x + CW - 1, y + CH - 1], outline=BORDER)
    _region_tab(d, x + 8, y + 7, region)
    f_h = _font(True, 13)
    yy = y + 68
    for ln in _wrap_max(d, headline, f_h, CW - 20, 2):
        d.text((x + 10, yy), ln, font=f_h, fill=INK)
        yy += 15
    f_d = _font(False, 10)
    yy = y + 100
    for ln in _wrap_max(d, detail, f_d, CW - 20, 2):
        d.text((x + 10, yy), ln, font=f_d, fill=(74, 72, 66))
        yy += 12
    f_s = _font(True, 15)
    d.text((x + 10, y + 129), stat, font=f_s, fill=REGION_COLORS[region])
    f_c = _font(True, 9)
    cw = int(_tw(d, source, f_c)) + 14
    _chip(d, x + CW - 10 - cw, y + 130, source, REGION_COLORS[region], f_c)


def _draw_cards(d):
    for i, card in enumerate(CARDS):
        row, col = divmod(i, 3)
        x = M + col * (CW + 10)
        y = GRID_Y + row * (CH + GAP)
        _draw_card(d, x, y, card)


def _draw_timeline(d):
    d.rectangle([M, 764, W - M - 1, 834], fill=CARD, outline=BORDER)
    d.text((24, 771), "THE DAY IN UTC", font=_font(True, 10), fill=NAVY)
    x0, x1 = 170, 1000
    d.line([(x0, 802), (x1, 802)], fill=BORDER, width=2)
    f_t = _font(True, 9)
    f_e = _font(False, 9)
    for i, (time, event) in enumerate(TIMELINE):
        cx = x0 + (i + 0.5) * (x1 - x0) / 8.0
        d.text((cx - _tw(d, time, f_t) / 2, 783), time, font=f_t, fill=NAVY)
        d.ellipse([cx - 4, 798, cx + 4, 806], fill=GOLD, outline=NAVY)
        yy = 810
        for ln in _wrap_max(d, event, f_e, 98, 2):
            d.text((cx - _tw(d, ln, f_e) / 2, yy), ln, font=f_e, fill=INK)
            yy += 11


def _draw_numbers(d):
    d.rectangle([M, 842, W - M - 1, 900], fill=CARD, outline=BORDER)
    d.text((24, 848), "THE DAY IN NUMBERS", font=_font(True, 9), fill=NAVY)
    f_v = _font(True, 15)
    f_l = _font(False, 9)
    for i, (value, label) in enumerate(NUMBERS):
        cx = M + (i + 0.5) * (W - 2 * M) / 8.0
        d.text((cx - _tw(d, value, f_v) / 2, 860), value, font=f_v, fill=NAVY2)
        yy = 879
        for ln in _wrap_max(d, label, f_l, 116, 2):
            d.text((cx - _tw(d, ln, f_l) / 2, yy), ln, font=f_l, fill=MUTED)
            yy += 10


def _draw_also_on(d):
    d.rectangle([M, 908, W - M - 1, 1014], fill=CARD, outline=BORDER)
    d.text((24, 915), "ALSO ON 25 NOVEMBER —", font=_font(True, 10), fill=NAVY)
    items = "   •   ".join("%s (%s)" % (h, s) for h, s in ALSO_ON)
    f_i = _font(False, 9)
    yy = 930
    for ln in _wrap_max(d, items, f_i, W - 2 * M - 20, 6):
        d.text((24, yy), ln, font=f_i, fill=INK)
        yy += 11
    # legend: region colour dots + names, then note at the right
    f_l = _font(False, 9)
    lx = 24
    ly = 1001
    for region in ("Europe", "Middle East", "Asia", "North America",
                   "Africa", "Oceania", "South America"):
        d.ellipse([lx, ly + 2, lx + 7, ly + 9], fill=REGION_COLORS[region])
        lx += 11
        d.text((lx, ly), region, font=f_l, fill=MUTED)
        lx += int(_tw(d, region, f_l)) + 12
    note = "Chips show the source  •  All times UTC  •  Scenes drawn by this program"
    d.text((1000 - _tw(d, note, f_l), ly), note, font=f_l, fill=MUTED)


def build_image():
    img = Image.new("RGB", (W, H), PAPER)
    d = ImageDraw.Draw(img)
    _draw_header(d)
    _draw_cards(d)
    _draw_timeline(d)
    _draw_numbers(d)
    _draw_also_on(d)
    return img


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    img = build_image()
    img.save(os.path.join(out_dir, "entry.png"), format="PNG", optimize=True)


if __name__ == "__main__":
    main()
